<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap/app.php';
$user=pf_require_advertiser($pdo);$error='';
$placements=$pdo->query("SELECT p.placement_key,p.label,p.description,pr.currency,pr.price_per_day,pr.min_duration_days,pr.max_duration_days FROM pf_ad_placements p JOIN pf_ad_placement_prices pr ON pr.placement_key=p.placement_key WHERE p.surface='BLOG' AND pr.is_active=1 AND pr.price_per_day>0 ORDER BY p.sort_order,p.label,pr.currency")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){
 pf_verify_csrf();$title=trim((string)($_POST['title']??''));$summary=trim((string)($_POST['summary']??''));$url=trim((string)($_POST['destination_url']??''));$placementToken=(string)($_POST['placement']??'');$start=(string)($_POST['start_date']??'');$end=(string)($_POST['end_date']??'');$parts=parse_url($url);$valid=static fn(string $d):bool=>preg_match('/\A\d{4}-\d{2}-\d{2}\z/',$d)===1&&date('Y-m-d',strtotime($d))===$d;
 $selected=null;foreach($placements as $p)if($p['placement_key'].'|'.$p['currency']===$placementToken){$selected=$p;break;}
 if($title===''||strlen($title)>180||$summary===''||strlen($summary)>500||!filter_var($url,FILTER_VALIDATE_URL)||strtolower((string)($parts['scheme']??''))!=='https'||empty($parts['host'])||!$selected||!$valid($start)||!$valid($end)||$start<date('Y-m-d')||$end<$start)$error='Check the title, short message, HTTPS destination, placement and campaign dates.';
 else{$days=(int)(new DateTimeImmutable($start))->diff(new DateTimeImmutable($end))->days+1;if($days<(int)$selected['min_duration_days']||$days>(int)$selected['max_duration_days'])$error='The selected blog placement does not support this duration.';
  else{$budget=round((float)$selected['price_per_day']*$days,2);if($budget<=0)$error='This blog placement has not been priced yet.';else try{
   $pdo->beginTransaction();$slug=strtolower(trim((string)preg_replace('/[^a-z0-9]+/i','-',$title),'-')).'-'.bin2hex(random_bytes(4));$starts=$start.' 00:00:00';$ends=$end.' 23:59:59';
   $q=$pdo->prepare("INSERT INTO pf_campaigns(advertiser_id,campaign_type,title,slug,summary,description,destination_url,reward_per_completion,total_quantity,approved_quantity,reserved_budget,spent_budget,currency,evidence_required,starts_at,ends_at,status) VALUES (?,'BLOG_SPONSORED',?,?,?,?,?,0,0,0,0,0,?,0,?,?,'DRAFT')");
   $q->execute([(int)$user['id'],$title,$slug,$summary,$summary,$url,$selected['currency'],$starts,$ends]);$id=(int)$pdo->lastInsertId();
   $creative=['name'=>$title,'summary'=>$summary,'placement'=>$selected['placement_key'],'image'=>'','url'=>$url,'status'=>'paused','start_date'=>$start,'end_date'=>$end];
   $pdo->prepare("INSERT INTO pf_blog_campaigns(campaign_id,public_token_hash,placement_key,requested_budget,creative_json,starts_at,ends_at,status,sync_status) VALUES (?,?,?,?,?,?,?,'PENDING','PENDING')")->execute([$id,hash('sha256',random_bytes(32)),$selected['placement_key'],$budget,json_encode($creative,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES),$starts,$ends]);
   $pdo->commit();header('Location: fund-blog-campaign.php?id='.$id);exit;
  }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('PoketFlow blog campaign creation failed: '.$e->getMessage());$error='The blog campaign could not be saved. Please try again.';}}
 }
}
$list=$pdo->prepare("SELECT c.id,c.title,c.status,c.currency,c.created_at,b.placement_key,b.requested_budget,b.sync_status,b.last_sync_error,b.starts_at,b.ends_at,(SELECT COUNT(*) FROM pf_blog_events e WHERE e.campaign_id=c.id AND e.event_type='IMPRESSION') impressions,(SELECT COUNT(*) FROM pf_blog_events e WHERE e.campaign_id=c.id AND e.event_type='CLICK') clicks FROM pf_campaigns c JOIN pf_blog_campaigns b ON b.campaign_id=c.id WHERE c.advertiser_id=? AND c.campaign_type='BLOG_SPONSORED' ORDER BY c.created_at DESC");$list->execute([(int)$user['id']]);$campaigns=$list->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Blog advertising | PoketFlow</title><link rel="stylesheet" href="assets/marketplace.css"><style>.stack{display:grid;gap:10px}.stack input,.stack select,.stack textarea{padding:12px;border:1px solid var(--line);border-radius:12px;font:inherit;width:100%}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left}th,td{padding:11px;border-bottom:1px solid var(--line);white-space:nowrap}</style></head><body><header class="topbar"><a class="brand" href="index.php"><span class="brand-mark">P</span><span>Poket<span>Flow</span></span></a><nav><a href="dashboard.php">Dashboard</a><a href="campaigns.php">Main-site ads</a><a href="wallet.php">Wallet</a><a href="funding.php">Add funds</a><a href="logout.php">Sign out</a></nav></header><main class="container"><section class="welcome"><p class="eyebrow">BLOG ADVERTISING</p><h1>Reach blog readers</h1><p class="muted">Request a clearly labelled sponsored placement on blog.poketflow.com. Placement prices and duration limits are configured by PoketFlow administrators.</p></section><?php if($error):?><div class="alert"><?=pf_e($error)?></div><?php endif;?>
<section class="panel"><h2>Create a blog campaign</h2><?php if(!$placements):?><p class="muted">No blog placements are currently available. Pricing and inventory must be configured first.</p><?php else:?><form class="stack" method="post"><input type="hidden" name="_token" value="<?=pf_e(pf_csrf_token())?>"><label>Ad / business title</label><input name="title" maxlength="180" required><label>Short ad message</label><textarea name="summary" maxlength="500" rows="3" required></textarea><label>HTTPS destination URL</label><input type="url" name="destination_url" placeholder="https://example.com" required><label>Blog placement and currency</label><select name="placement" required><?php foreach($placements as $p):?><option value="<?=pf_e($p['placement_key'].'|'.$p['currency'])?>"><?=pf_e($p['label'])?> — <?=pf_e($p['currency'])?> <?=number_format((float)$p['price_per_day'],2)?> per day</option><?php endforeach;?></select><label>Start date</label><input type="date" name="start_date" min="<?=date('Y-m-d')?>" required><label>End date</label><input type="date" name="end_date" min="<?=date('Y-m-d')?>" required><p class="small muted">The total is calculated from the configured daily rate and schedule. All sponsored content is reviewed before publication; no impression volume is guaranteed.</p><button class="button primary" type="submit">Create blog campaign</button></form><?php endif;?></section>
<section class="panel" style="margin-top:24px"><h2>Your blog campaigns</h2><div class="table-wrap"><table><thead><tr><th>Campaign</th><th>Placement</th><th>Dates</th><th>Budget</th><th>Impressions</th><th>Clicks</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($campaigns as $c):?><tr><td><?=pf_e($c['title'])?></td><td><?=pf_e($c['placement_key'])?></td><td><?=pf_e(substr((string)$c['starts_at'],0,10))?> – <?=pf_e(substr((string)$c['ends_at'],0,10))?></td><td><?=pf_e($c['currency'])?> <?=number_format((float)$c['requested_budget'],2)?></td><td><?=number_format((int)$c['impressions'])?></td><td><?=number_format((int)$c['clicks'])?></td><td><?=pf_e($c['status'])?></td><td><?php if($c['status']==='DRAFT'):?><a href="fund-blog-campaign.php?id=<?=(int)$c['id']?>">Review & reserve</a><?php else:?><?=pf_e($c['sync_status'])?><?php endif;?></td></tr><?php endforeach;?><?php if(!$campaigns):?><tr><td colspan="8">No blog campaigns yet.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
